def prefix():
    return '../' * len(ROUTE.split('/')) if ROUTE else './'

def url(route=''):
    if route.startswith(('https://','http://','mailto:','tel:','sms:')): return route
    if '#' in route:
        path, fragment = route.split('#',1)
    else: path,fragment=route,''
    result = prefix() + ((path.strip('/') + '/') if path.strip('/') else '') + 'index.html'
    return result + ('#'+fragment if fragment else '')

def asset(name): return prefix() + name

def a(text, route, cls='text-link', arrow=True, attrs=''):
    external = ' target="_blank" rel="noopener noreferrer"' if route.startswith('https://') else ''
    return f'<a class="{cls}" href="{E(url(route),quote=True)}"{external} {attrs}>{text}{ARROW if arrow else ""}</a>'

def quiz_button(text='Take the quiz', cls='button', arrow=True):
    return a(text,CONFIG['quiz_url'],cls,arrow)

def eye(text, cls=''):
    return f'<span class="eyebrow {cls}">{text}</span>'

def image(name, alt, cls='', eager=False, attrs=''):
    dims = next((i for i in ASSETS if i['asset']==f'assets/images/{name}.webp'),{})
    wh = f' width="{dims.get("width",900)}" height="{dims.get("height",650)}"'
    loading='fetchpriority="high" loading="eager"' if eager else 'loading="lazy"'
    return f'<img src="{asset("assets/images/"+name+".webp")}" alt="{E(alt,quote=True)}" class="{cls}" {loading} decoding="async"{wh} {attrs}>'

def brand():
    return f'<a class="brand" href="{url()}" aria-label="Doppler Wellness home"><img src="{asset("assets/mark.svg")}" alt="" width="39" height="39"><span class="wordmark"><strong>DOPPLER</strong><small>WELLNESS</small></span></a>'

def nav():
    care_routes=['care','our-approach','mindfulness','at-home-therapy','in-person-therapy','insurance','questions']
    care_active=ROUTE in care_routes or ROUTE.startswith('care/')
    menu_links=[('Our approach','our-approach'),('Mindfulness','mindfulness'),('At-home therapy','at-home-therapy'),('In-person therapy','in-person-therapy'),('What we help with','care'),('Insurance','insurance'),('Questions','questions')]
    def nav_link(label,r):
        current=' aria-current="page"' if ROUTE==r else ''
        return f'<a class="nav-link" href="{url(r)}"{current}>{label}</a>'
    dropdown=''.join(f'<a href="{url(r)}">{label}{ARROW}</a>' for label,r in menu_links)
    return f'''<a class="skip" href="#main">Skip to content</a>
<header class="site-header"><div class="nav-shell">{brand()}
<nav class="nav-links" id="main-navigation" aria-label="Main navigation" data-main-nav>
{nav_link('Home','')}<details class="care-menu {'active' if care_active else ''}"><summary>Care <span aria-hidden="true">+</span></summary><div class="care-dropdown">{dropdown}</div></details>
{nav_link('Mission','mission')}{nav_link('Tools','tools')}{nav_link('Journal','journal')}{nav_link('For clinicians','for-clinicians')}{nav_link('Contact','contact')}
</nav>{quiz_button(cls='button nav-cta')}<button class="menu-toggle" type="button" aria-label="Open navigation" aria-controls="main-navigation" aria-expanded="false" data-menu-toggle><span></span><span></span></button>
</div></header>'''

