def concern_cards(rail=False):
    cards=''.join(f'<a class="concern-card" href="{url("care/"+slug)}"><div class="card-top">{eye(label)}{ARROW}</div><h3>{heading}</h3><p>{copy}</p></a>' for slug,label,heading,copy,_,_ in CONCERNS)
