def match_panel():
    tabs=[('What you’re carrying','Start with what has become harder.','The concerns, patterns, experiences, and goals you choose to share help create a clearer starting point.'),('How you want to work','Make room for the way you open up.','Some people want space to process. Others want practical direction. Your preferences belong in the conversation.'),('What care must fit around','The practical details matter, too.','Discuss your location, the format you prefer, scheduling needs, eligibility, and coverage before care begins.')]
    tab_html=''.join(f'<button class="tab" type="button" role="tab" id="match-tab-{i}" aria-controls="match-panel-{i}" aria-selected="{str(i==0).lower()}" tabindex="{0 if i==0 else -1}">{h}</button>' for i,(h,_,_) in enumerate(tabs))
    panels=''.join(f'<div class="tab-panel" role="tabpanel" id="match-panel-{i}" aria-labelledby="match-tab-{i}" {"hidden" if i else ""}>{eye(h)}<h4>{t}</h4><p>{p}</p></div>' for i,(h,t,p) in enumerate(tabs))
    return f'<div class="match-panel" data-tabs>{eye("A considered starting point")}<h3>Not an endless directory.</h3><div class="tabs" role="tablist" aria-label="What shapes your starting point">{tab_html}</div>{panels}</div>'

