def breath_tool():
    return f'''<div class="breath-tool" data-breath-tool><div class="tool-bar"><div class="tool-brand"><span class="tool-icon" aria-hidden="true"></span><span><strong>Doppler Pause</strong><small>GUIDED BREATHING</small></span></div><span class="pill"><i></i>Silent by default</span></div><div class="tool-body"><div class="breath-visual" aria-hidden="true"><div class="breath-orbits"><i class="orbit"></i><i class="orbit"></i><i class="orbit"></i><div class="orb"></div></div><span class="visual-cue" data-breath-visual-cue>Follow at a comfortable pace.</span></div><div class="tool-copy">{eye('A small reset, right where you are')}<h3 data-breath-cue aria-live="polite" aria-atomic="true">Take one easy breath.</h3><p>Follow the light at a comfortable pace. There is no need to breathe more deeply than feels natural.</p><div class="tool-options"><label class="sr-only" for="breath-duration">Practice duration</label><select id="breath-duration" data-breath-duration><option value="60">About one minute</option><option value="30">About 30 seconds</option></select><label class="checkbox-label"><input type="checkbox" data-breath-text> Text cues only</label></div><div class="tool-controls"><button class="button" type="button" data-breath-start>Start breathing</button><button class="button outline" type="button" data-breath-reset>Reset</button></div><progress class="tool-progress" max="60000" value="0" data-breath-progress aria-label="Practice progress"></progress><div class="tool-status" data-breath-status>Ready when you are.</div><div class="tool-secondary">{a('Use grounding instead','tools/grounding')}</div></div></div><div class="tool-footer"><p>Optional, general-wellness practice—not treatment. Stop if you feel uncomfortable or lightheaded. Keep your eyes open if that feels better.</p>{a('Choose another anchor','tools')}</div></div>'''

